@Aspect
@Component
public class TraceAspect {

    @Before("execution(* com.acme.Svc.run(..))")
    public void before() { System.out.print("B"); }

    @After("execution(* com.acme.Svc.run(..))")
    public void after() { System.out.print("A"); }

    @AfterReturning("execution(* com.acme.Svc.run(..))")
    public void afterReturning() { System.out.print("R"); }

    @Around("execution(* com.acme.Svc.run(..))")
    public Object around(ProceedingJoinPoint pjp) throws Throwable {
        System.out.print("[");
        Object result = pjp.proceed();
        System.out.print("]");
        return result;
    }
}

